-- Finance F5: generated documents (docs/finance-documents-f5.md). Document branding, branding assets
-- (logos) and immutable PDF versions of issued quotes and invoices. Generated by `prisma migrate diff`,
-- then the constraints, guards, grants and RLS Prisma cannot express were added by hand (marked
-- "hand-written"). Wrapped in one explicit transaction (STAB-01, docs/migration-readiness.md §7): a
-- failure leaves nothing behind.
--
-- Ordering: depends on 20261115000000_finance (finance_documents and its kind key, enums,
-- finance_stamp_times) and 20261113150000_tenancy. Touches no existing table, column, grant or policy,
-- so it is additive and may be applied before or after 20261121000000_communications_providers (C2-A).
-- No extensions: sha256() and octet_length() are built into PostgreSQL 11+.
--
-- Storage (owner decision F5-D1): PDF and logo bytes live in bytea columns here because Business OS has
-- no object storage. Limits are CHECKs: logos <= 512 KiB, PDFs <= 4 MiB, <= 50 versions per document.

BEGIN;

-- CreateTable
CREATE TABLE "finance_document_branding" (
    "business_id" UUID NOT NULL,
    "accent_color" TEXT NOT NULL DEFAULT '#1F4B99',
    "logo_asset_id" UUID,
    "footer_text" TEXT,
    "invoice_title" TEXT,
    "invoice_terms" TEXT,
    "quote_title" TEXT,
    "quote_terms" TEXT,
    "template_id" TEXT NOT NULL DEFAULT 'standard',
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_by_id" UUID,
    "updated_by_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_document_branding_pkey" PRIMARY KEY ("business_id")
);

-- CreateTable
CREATE TABLE "finance_branding_assets" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "content_type" TEXT NOT NULL,
    "byte_size" INTEGER NOT NULL,
    "width" INTEGER NOT NULL,
    "height" INTEGER NOT NULL,
    "sha256" CHAR(64) NOT NULL,
    "data" BYTEA NOT NULL,
    "created_by_id" UUID NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_branding_assets_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "finance_document_pdfs" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "document_id" UUID NOT NULL,
    "document_kind" "FinanceDocumentKind" NOT NULL,
    "version_number" INTEGER NOT NULL,
    "reason" TEXT NOT NULL,
    "reason_note" TEXT,
    "previous_version_id" UUID,
    "document_number" TEXT NOT NULL,
    "document_status" "FinanceDocumentStatus" NOT NULL,
    "document_content_sha256" CHAR(64) NOT NULL,
    "template_id" TEXT NOT NULL,
    "template_version" INTEGER NOT NULL,
    "renderer" TEXT NOT NULL,
    "snapshot" JSONB NOT NULL,
    "snapshot_sha256" CHAR(64) NOT NULL,
    "logo_asset_id" UUID,
    "file_name" TEXT NOT NULL,
    "content_type" TEXT NOT NULL DEFAULT 'application/pdf',
    "page_count" INTEGER NOT NULL,
    "unsupported_characters" BOOLEAN NOT NULL DEFAULT false,
    "byte_size" INTEGER NOT NULL,
    "file_sha256" CHAR(64) NOT NULL,
    "file_data" BYTEA NOT NULL,
    "generated_by_id" UUID NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "finance_document_pdfs_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "finance_branding_assets_business_id_created_at_idx" ON "finance_branding_assets"("business_id", "created_at");

-- CreateIndex
CREATE UNIQUE INDEX "finance_branding_assets_business_id_id_key" ON "finance_branding_assets"("business_id", "id");

-- CreateIndex
CREATE INDEX "finance_document_pdfs_business_id_document_id_created_at_idx" ON "finance_document_pdfs"("business_id", "document_id", "created_at");

-- CreateIndex
CREATE UNIQUE INDEX "finance_document_pdfs_business_id_id_key" ON "finance_document_pdfs"("business_id", "id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_document_pdfs_chain_key" ON "finance_document_pdfs"("business_id", "document_id", "id");

-- CreateIndex
CREATE UNIQUE INDEX "finance_document_pdfs_business_id_document_id_version_numbe_key" ON "finance_document_pdfs"("business_id", "document_id", "version_number");

-- AddForeignKey
ALTER TABLE "finance_document_branding" ADD CONSTRAINT "finance_document_branding_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_document_branding" ADD CONSTRAINT "finance_document_branding_logo_fkey" FOREIGN KEY ("business_id", "logo_asset_id") REFERENCES "finance_branding_assets"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_branding_assets" ADD CONSTRAINT "finance_branding_assets_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_document_pdfs" ADD CONSTRAINT "finance_document_pdfs_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "finance_document_pdfs" ADD CONSTRAINT "finance_document_pdfs_document_fkey" FOREIGN KEY ("business_id", "document_id", "document_kind") REFERENCES "finance_documents"("business_id", "id", "kind") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_document_pdfs" ADD CONSTRAINT "finance_document_pdfs_logo_fkey" FOREIGN KEY ("business_id", "logo_asset_id") REFERENCES "finance_branding_assets"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "finance_document_pdfs" ADD CONSTRAINT "finance_document_pdfs_previous_fkey" FOREIGN KEY ("business_id", "document_id", "previous_version_id") REFERENCES "finance_document_pdfs"("business_id", "document_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;


-- ============================================================================================
-- hand-written
-- ============================================================================================

-- ---- finance_document_branding ---------------------------------------------------------------
ALTER TABLE "finance_document_branding"
  ADD CONSTRAINT finance_document_branding_accent_format CHECK ("accent_color" ~ '^#[0-9A-F]{6}$'),
  ADD CONSTRAINT finance_document_branding_template_values CHECK ("template_id" IN ('standard')),
  ADD CONSTRAINT finance_document_branding_footer_length CHECK ("footer_text" IS NULL OR char_length("footer_text") BETWEEN 1 AND 500),
  ADD CONSTRAINT finance_document_branding_titles_length CHECK (
    ("invoice_title" IS NULL OR char_length(btrim("invoice_title")) BETWEEN 1 AND 60)
    AND ("quote_title" IS NULL OR char_length(btrim("quote_title")) BETWEEN 1 AND 60)),
  ADD CONSTRAINT finance_document_branding_terms_length CHECK (
    ("invoice_terms" IS NULL OR char_length("invoice_terms") BETWEEN 1 AND 2000)
    AND ("quote_terms" IS NULL OR char_length("quote_terms") BETWEEN 1 AND 2000)),
  ADD CONSTRAINT finance_document_branding_version_positive CHECK ("version" >= 1);
CREATE TRIGGER finance_stamp_times BEFORE INSERT OR UPDATE ON "finance_document_branding" FOR EACH ROW EXECUTE FUNCTION finance_stamp_times();

-- ---- finance_branding_assets (insert-only) ---------------------------------------------------
ALTER TABLE "finance_branding_assets"
  ADD CONSTRAINT finance_branding_assets_type_values CHECK ("content_type" IN ('image/png', 'image/jpeg')),
  ADD CONSTRAINT finance_branding_assets_size_range CHECK ("byte_size" BETWEEN 1 AND 524288),
  ADD CONSTRAINT finance_branding_assets_dimensions CHECK ("width" BETWEEN 1 AND 2000 AND "height" BETWEEN 1 AND 2000),
  ADD CONSTRAINT finance_branding_assets_sha_format CHECK ("sha256" ~ '^[0-9a-f]{64}$');

-- Size, checksum and time are database-owned: whatever the client sent is replaced.
CREATE FUNCTION finance_stamp_branding_asset() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  NEW.byte_size := octet_length(NEW.data);
  NEW.sha256 := encode(sha256(NEW.data), 'hex');
  NEW.created_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER finance_stamp_branding_asset BEFORE INSERT ON "finance_branding_assets" FOR EACH ROW EXECUTE FUNCTION finance_stamp_branding_asset();

-- ---- finance_document_pdfs (insert-only versions) --------------------------------------------
ALTER TABLE "finance_document_pdfs"
  ADD CONSTRAINT finance_document_pdfs_kind_values CHECK ("document_kind" IN ('QUOTE', 'INVOICE')),
  ADD CONSTRAINT finance_document_pdfs_version_range CHECK ("version_number" BETWEEN 1 AND 50),
  ADD CONSTRAINT finance_document_pdfs_reason_values CHECK ("reason" IN ('ORIGINAL', 'BRANDING_UPDATED', 'TEMPLATE_UPDATED', 'RENDERING_CORRECTION', 'OTHER')),
  -- Version 1 is the original and only it is; every later version names the one it follows.
  ADD CONSTRAINT finance_document_pdfs_original CHECK (("version_number" = 1) = ("reason" = 'ORIGINAL')),
  ADD CONSTRAINT finance_document_pdfs_chain CHECK (("version_number" = 1) = ("previous_version_id" IS NULL)),
  ADD CONSTRAINT finance_document_pdfs_note CHECK (
    ("reason_note" IS NULL OR char_length(btrim("reason_note")) BETWEEN 1 AND 500) AND ("reason" <> 'OTHER' OR "reason_note" IS NOT NULL)),
  ADD CONSTRAINT finance_document_pdfs_status_values CHECK ("document_status" <> 'DRAFT'),
  -- F5-D2: the original is the issued representation, made in the issuing transaction (status ISSUED).
  ADD CONSTRAINT finance_document_pdfs_original_issued CHECK ("version_number" <> 1 OR "document_status" = 'ISSUED'),
  ADD CONSTRAINT finance_document_pdfs_hashes CHECK (
    "document_content_sha256" ~ '^[0-9a-f]{64}$' AND "snapshot_sha256" ~ '^[0-9a-f]{64}$' AND "file_sha256" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT finance_document_pdfs_file CHECK (
    "content_type" = 'application/pdf' AND "byte_size" BETWEEN 1 AND 4194304 AND "page_count" BETWEEN 1 AND 500
    AND "file_name" ~ '^[A-Za-z0-9._-]{1,120}\.pdf$'),
  ADD CONSTRAINT finance_document_pdfs_template CHECK ("template_id" IN ('standard') AND "template_version" >= 1 AND char_length("renderer") BETWEEN 1 AND 100),
  ADD CONSTRAINT finance_document_pdfs_snapshot_object CHECK (jsonb_typeof("snapshot") = 'object');

-- The guard (SECURITY INVOKER: runs as the caller, under RLS). A version can only be added for a
-- numbered (issued or later) document of this business, must carry that document's number and sealed
-- content hash, and must be the next number after the latest version, following it. Checksums, size
-- and time are database-owned. The service serialises generation per document with an advisory lock;
-- the unique (business_id, document_id, version_number) index is the backstop.
CREATE FUNCTION finance_guard_document_pdf() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  doc record;
  latest record;
BEGIN
  SELECT status, number, content_sha256 INTO doc FROM finance_documents
    WHERE business_id = NEW.business_id AND id = NEW.document_id AND kind = NEW.document_kind;
  IF NOT FOUND OR doc.status = 'DRAFT' OR doc.number IS NULL
     OR doc.number IS DISTINCT FROM NEW.document_number OR doc.content_sha256 IS DISTINCT FROM NEW.document_content_sha256
     OR doc.status IS DISTINCT FROM NEW.document_status THEN
    RAISE EXCEPTION 'document is not eligible for a PDF version' USING ERRCODE = 'FN019';
  END IF;
  SELECT id, version_number INTO latest FROM finance_document_pdfs
    WHERE business_id = NEW.business_id AND document_id = NEW.document_id ORDER BY version_number DESC LIMIT 1;
  IF NEW.version_number IS DISTINCT FROM coalesce(latest.version_number, 0) + 1
     OR NEW.previous_version_id IS DISTINCT FROM latest.id THEN
    RAISE EXCEPTION 'PDF version out of sequence' USING ERRCODE = 'FN020';
  END IF;
  NEW.byte_size := octet_length(NEW.file_data);
  NEW.file_sha256 := encode(sha256(NEW.file_data), 'hex');
  NEW.snapshot_sha256 := encode(sha256(convert_to(NEW.snapshot::text, 'UTF8')), 'hex');
  NEW.created_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER finance_guard_document_pdf BEFORE INSERT ON "finance_document_pdfs" FOR EACH ROW EXECUTE FUNCTION finance_guard_document_pdf();

-- Defence in depth behind the grants: neither assets nor versions ever change or disappear, for any
-- role that reaches them through normal DML (the owner included).
CREATE FUNCTION finance_document_files_immutable() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  RAISE EXCEPTION 'generated documents and branding assets are immutable' USING ERRCODE = 'FN021';
END $$;
CREATE TRIGGER finance_document_pdfs_immutable BEFORE UPDATE OR DELETE ON "finance_document_pdfs" FOR EACH ROW EXECUTE FUNCTION finance_document_files_immutable();
CREATE TRIGGER finance_branding_assets_immutable BEFORE UPDATE OR DELETE ON "finance_branding_assets" FOR EACH ROW EXECUTE FUNCTION finance_document_files_immutable();

REVOKE ALL ON FUNCTION finance_stamp_branding_asset(), finance_guard_document_pdf(), finance_document_files_immutable() FROM PUBLIC;

-- ---- least privilege ---------------------------------------------------------------------------
-- bos_owner's default privileges are revoked first. No DELETE anywhere; versions and assets are
-- insert-only; branding is updated by column grant.
REVOKE ALL ON "finance_document_branding", "finance_branding_assets", "finance_document_pdfs" FROM bos_app;
GRANT SELECT, INSERT ON "finance_document_branding", "finance_branding_assets", "finance_document_pdfs" TO bos_app;
GRANT UPDATE ("accent_color", "logo_asset_id", "footer_text", "invoice_title", "invoice_terms", "quote_title", "quote_terms",
  "template_id", "version", "updated_by_id", "updated_at") ON "finance_document_branding" TO bos_app;

-- ---- row-level security --------------------------------------------------------------------------
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['finance_document_branding', 'finance_branding_assets', 'finance_document_pdfs'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($p$CREATE POLICY tenant_isolation ON %I FOR ALL TO bos_app
      USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
      WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)$p$, t);
  END LOOP;
END $$;
-- Authorship: a version or an asset is created by the user of the unit of work.
CREATE POLICY generated_by_session_user ON "finance_document_pdfs" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("generated_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY created_by_session_user ON "finance_branding_assets" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("created_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);

COMMIT;
